// TC-BR-095: every contract number carries the same fixed leading
// partner-marker character, applied by the build, not merely passed
// through from source data.
CASES.push({
  tcId: 'TC-BR-095', rule: 'BR-095',
  run: async (console) => {
    const seq = seqFor('BR-095');
    const firmA = buildFirm(seq);
    const firmB = buildFirm(seq + 1);
    const fn = 'ALLSTATE.LNA.BR-095-CANDIDATE.D20260908.txt';
    assembleFile(fn, [[firmA.B, firmA.C], [firmB.B, firmB.C]]);
    const { status } = await uploadAndSettle(console, fn);
    return withDb(async (client) => {
      const a = await client.query('SELECT pru_contract_number FROM pru_adb.contract WHERE allstate_id = $1', [firmA.id.bd]);
      const b = await client.query('SELECT pru_contract_number FROM pru_adb.contract WHERE allstate_id = $1', [firmB.id.bd]);
      const numA = a.rows[0]?.pru_contract_number || '';
      const numB = b.rows[0]?.pru_contract_number || '';
      return [
        { description: 'run completed', pass: status === 'COMPLETED', detail: `status=${status}` },
        { description: 'two independently-built contract numbers share the identical first character (a fixed marker, not derived from source data)', pass: numA.length > 0 && numB.length > 0 && numA[0] === numB[0], detail: `A="${numA}", B="${numB}"` },
      ];
    });
  },
});

