// ---------------------------------------------------------------------
// The following two rules were previously blocked as "needs the ADSIMSTR
// mainframe-vs-Java comparator". Their actual expectations turned out to
// be self-contained facts about the raw ADSIMSTR extract's own bytes -
// checkable directly, since ADSIMSTR.cpy (the copybook) ships inside the
// same "download all artifacts" ZIP this project already uses elsewhere.
// See utils/adsimstr-parser.brv4.ts.
// ---------------------------------------------------------------------

// TC-BR-107: the master record is a record of counted sections - every
// section added is counted three times (within its own kind, within its
// occurrences, and in the record's overall total), and all three must
// agree.
CASES.push({
  tcId: 'TC-BR-107', rule: 'BR-107',
  run: async (console) => {
    const seq = seqFor('BR-107');
    const firm = buildFirm(seq);
    const prod = buildProducer(seq + 1, firm.id.bd, firm.id.bd, 'A');
    const fn = 'ALLSTATE.LNA.BR-107-CANDIDATE.D20260908.txt';
    assembleFile(fn, [[firm.B, firm.C, prod.D1, prod.D2]]);
    const { runId, status } = await uploadAndSettle(console, fn);
    const record = await downloadAndFindAdsimstrRecord(console, runId, prod.id.ssn);
    if (!record) return [{ description: 'the producer\'s record was found in the downloaded ADSIMSTR extract', pass: false, detail: 'not found' }];
    const totSections = ADSIMSTR.totNumOfSections(record.raw);
    const perKind: Array<{ n: number; master: number; occur: number }> = [];
    let sumOccur = 0;
    for (let n = 1; n <= 9; n++) {
      const master = ADSIMSTR.basicMaster(record.raw, n);
      const occur = ADSIMSTR.basicOccur(record.raw, n);
      perKind.push({ n, master, occur });
      sumOccur += occur;
    }
    const allAgree = perKind.every((k) => k.master === k.occur);
    return [
      { description: 'run completed', pass: status === 'COMPLETED', detail: `status=${status}` },
      { description: 'for every BASICn kind, its own MASTER count agrees with its own OCCUR count', pass: allAgree, detail: JSON.stringify(perKind) },
      { description: 'the sum of every kind\'s OCCUR count agrees with the record\'s overall ALL-TOT-NUM-OF-SECTIONS', pass: sumOccur === totSections, detail: `sum(occur)=${sumOccur}, totSections=${totSections}` },
    ];
  },
});

// TC-BR-109: a section is added to every appointment master record
// carrying nothing at all (BASIC2, past byte 850 - pure filler in
// ADSIMSTR.cpy, no named field at all - yet always occurs exactly once).
CASES.push({
  tcId: 'TC-BR-109', rule: 'BR-109',
  run: async (console) => {
    const seq = seqFor('BR-109');
    const firm = buildFirm(seq);
    const prod = buildProducer(seq + 1, firm.id.bd, firm.id.bd, 'A');
    const fn = 'ALLSTATE.LNA.BR-109-CANDIDATE.D20260908.txt';
    assembleFile(fn, [[firm.B, firm.C, prod.D1, prod.D2]]);
    const { runId, status } = await uploadAndSettle(console, fn);
    const record = await downloadAndFindAdsimstrRecord(console, runId, prod.id.ssn);
    if (!record) return [{ description: 'the producer\'s record was found in the downloaded ADSIMSTR extract', pass: false, detail: 'not found' }];
    const basic1Occur = ADSIMSTR.basicOccur(record.raw, 1);
    const basic2Occur = ADSIMSTR.basicOccur(record.raw, 2);
    const basic4Occur = ADSIMSTR.basicOccur(record.raw, 4);
    const totSections = ADSIMSTR.totNumOfSections(record.raw);
    return [
      { description: 'run completed', pass: status === 'COMPLETED', detail: `status=${status}` },
      { description: 'the always-present, no-data BASIC2 section is counted exactly once, even though it carries no visible content', pass: basic2Occur === 1, detail: `basic2Occur=${basic2Occur}` },
      { description: 'the overall section total includes that always-present section (not just the ones with visible data)', pass: totSections === basic1Occur + basic2Occur + basic4Occur, detail: `totSections=${totSections}, basic1=${basic1Occur}, basic2=${basic2Occur}, basic4=${basic4Occur}` },
    ];
  },
});

// TC-BR-111: a broker dealer alone carries a second, postal address in the
